arguments.command:
cd /tmp/vally-eval-trial-Fwid1f && P=.copilot-tracking/skraft-plans/pricing && mkdir -p $P/features $P/details/2026-10-09 $P/evidence/2026-10-09/discount tests/CheckoutPricing.UnitTest/LoyaltyDiscount
cat > $P/features/pricing-loyalty-discount.feature <<'EOF'
@loyalty-discount
Feature: Loyalty tier discount at checkout
  A returning customer's loyalty tier is reflected in the checkout total.

  # SETTLED: scenarios below carry the values of AC-1..AC-4 verbatim.
  # NOT DECIDED: see the final section. No scenario exists for it, on purpose.

  @happy-path @smoke
  Scenario: Bronze customer is charged the Bronze price for a basket
    Given a returning customer in the Bronze tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 9500 cents

  @happy-path
  Scenario: Silver customer is charged the Silver price for a basket
    Given a returning customer in the Silver tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 9000 cents

  @happy-path
  Scenario: Gold customer is charged the Gold price for a basket
    Given a returning customer in the Gold tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 8500 cents

  @edge-case
  Scenario: Bronze customer's reduction lands on a whole cent in the customer's favour
    Given a returning customer in the Bronze tier
    When a basket subtotal of 7 cents is priced
    Then the customer is charged 7 cents

  # ---------------------------------------------------------------
  # NOT DECIDED (no executable scenario, no expected value)
  # - Platinum tier: the business has not agreed a reduction (ac.md "Not decided").
  #   Escalated to DISCUSS. A scenario is added only once the business supplies
  #   one worked example (tier, subtotal, amount charged).
  # ---------------------------------------------------------------
EOF
cat > tests/CheckoutPricing.UnitTest/LoyaltyDiscount/LoyaltyDiscountAcceptanceTests.cs <<'EOF'
using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.LoyaltyDiscount;

[Trait("Category", "Acceptance")]
public class LoyaltyDiscountAcceptanceTests
{
    [Fact]
    public void Bronze_customer_is_charged_the_Bronze_price_for_a_basket()
    {
        var pricing = new CalculateLoyaltyDiscount();

        var quote = pricing.Handle(new CalculateLoyaltyDiscountQuery(10000, LoyaltyTier.Bronze));

        Assert.Equal(9500, quote.TotalCents);
    }
}
EOF
dotnet test tests/CheckoutPricing.UnitTest --filter "Category=Acceptance" > $P/evidence/2026-10-09/discount/acceptance-red.stdout 2>&1; echo $? > $P/evidence/2026-10-09/discount/acceptance-red.exit
git rev-parse HEAD > $P/evidence/2026-10-09/discount/acceptance-red.rev
cat $P/evidence/2026-10-09/discount/acceptance-red.exit; grep -E "Assert|Expected|Actual|error|Failed" $P/evidence/2026-10-09/discount/acceptance-red.stdout | head; cat $P/evidence/2026-10-09/discount/acceptance-red.rev

